INSERT INTO `tournament_match_summaries` (`id`,`event_id`,`round`,`best_of`,`leader_one_code`,`archetype_one`,`leader_two_code`,`archetype_two`,`score_one`,`score_two`,`winner_leader_code`,`winner_side`,`summary`,`source_name`,`source_url`,`evidence_status`) VALUES
('flame-flame-eu-2026-final-robin-enel','flame-flame-eu-coliseum-2026','Grand Final',3,'OP09-062','Purple/Yellow Nico Robin','OP15-058','Purple Enel',2,1,'OP09-062',1,'Purple/Yellow Nico Robin wins the Flame-Flame Fruit Coliseum EU grand final 2–1. Game 1: Enel has a slow opening while Robin ramps through leader banish and develops toward 10-cost Big Mom. Enel builds the Holly and M double-attack package and pressures Robin’s life, but a Pudding trigger finds Sweet 3 Generals. Robin survives, shrinks Enel’s attackers, clears the board, then plays Big Mom to heal and turn her trigger bodies into 8k attacks. Game 2: Enel finds early Shura and Dog pressure, then uses M, Holly, Senior Pink, and removal events to push Robin to zero life. Robin eventually reaches 10 DON and heals with Big Mom, but Enel has conserved counters and removal for the return turn and wins through Robin’s depleted hand. Game 3: Enel develops Dog, Shura, Holly, and Senior Pink, while Robin ramps without finding Big Mom. A Teach trigger removes Senior Pink during Enel’s lethal setup; Mont d’Or clears Enel’s one-cost Puddings, and Smoothie heals Robin while removing Gamma Knife from Enel’s hand. Enel’s final 8k M attack is met by Robin’s exact 4k counter. Robin then closes with repeated 5k–7k attacks, including Mont d’Or, while Enel lacks enough cards to defend. Robin wins the deciding game and the tournament.','User-provided video analysis summary','https://www.youtube.com/watch?v=WlnAznh3Mpc&t=1102s','VERIFIED'),
('flame-flame-eu-2026-semi-enel-sabo','flame-flame-eu-coliseum-2026','Semifinal',3,'OP15-058','Purple Enel','OP13-004','Red/Black Sabo',2,1,'OP15-058',1,'Purple Enel wins the semifinal 2–1. Game 1: Sabo goes first but misses a turn-one play. Enel develops Shura, M, and Holly, using leader ability to add rested DON to the attackers. Holly grants double attack to itself and M and makes them 6k on Sabo’s turn. Enel chains Mamaragan, Lightning Dragon, K-10, and El Thor to rest, shrink, and remove Sabo’s Usopp, Nami, and Sanji. M attacks for 8k double attack, then Holly reaches 10k double attack and takes Sabo from four life to zero while clearing the board. Sabo briefly stabilizes with Loki and 7-cost Zoro, but Enel’s blocker Law discards two cards from Sabo’s large hand and Enel closes; Sabo concedes. Game 2: Enel’s Dog/Holly line is less clean. Sabo leans on Jaguar D. Saul, Usopp, 7-cost Zoro, and repeated Loki removals, surviving Enel’s double-attack turns with careful counter use. Sabo holds enough counter for Enel’s 12k swing, then pushes back with Pirates Docking Six, Sanji, and multiple 7k–8k attacks to win. Game 3: Enel chooses to go first and quickly assembles M, Shura, Dog, and Holly. Sabo has Nami, Usopp, and Sanji, but Enel’s events keep the board small. Law discards Luffy and a counter event; Gamma Knife and Don Stamp remove Loki, while K-10, Mamaragan, and Lightning Dragon disrupt Nami and Luffy. Sabo develops Jinbe as a blocker and prepares a lethal turn, but Enel uses Gamma Knife and El Thor to remove Jinbe, then pumps Senior Pink and attacks with leader and his remaining bodies. Sabo cannot defend the attacks at zero life, and Enel wins the decider.','User-provided video analysis summary','https://www.youtube.com/watch?v=WlnAznh3Mpc&t=1102s','VERIFIED');
